package io.github.victorkolesnyk.hamir.data

import android.security.keystore.KeyGenParameterSpec
import android.security.keystore.KeyProperties
import io.github.victorkolesnyk.hamir.logic.WrappingKeySource
import java.security.KeyStore
import javax.crypto.KeyGenerator
import javax.crypto.SecretKey

/**
 * AES-256-GCM key in AndroidKeyStore that wraps the bank's data key (see logic/KeyEnvelope).
 * It never leaves the keystore, needs no user authentication and only accepts IVs generated by
 * the cipher. It is used once per process (unwrap) and once per bank (wrap), so its low speed
 * does not matter. All APIs used here exist since API 23.
 */
class KeystoreWrappingKey : WrappingKeySource {

    @Synchronized
    override fun existing(): SecretKey? = keyStore().getKey(ALIAS, null) as? SecretKey

    @Synchronized
    override fun getOrCreate(): SecretKey {
        existing()?.let { return it }
        val spec = KeyGenParameterSpec.Builder(
            ALIAS,
            KeyProperties.PURPOSE_ENCRYPT or KeyProperties.PURPOSE_DECRYPT,
        )
            .setKeySize(256)
            .setBlockModes(KeyProperties.BLOCK_MODE_GCM)
            .setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE)
            .setUserAuthenticationRequired(false)
            .build()
        val generator = KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES, PROVIDER)
        generator.init(spec)
        return generator.generateKey()
    }

    @Synchronized
    override fun delete() {
        val keyStore = keyStore()
        if (keyStore.containsAlias(ALIAS)) keyStore.deleteEntry(ALIAS)
    }

    private fun keyStore(): KeyStore = KeyStore.getInstance(PROVIDER).apply { load(null) }

    companion object {
        const val ALIAS = "hamir_bank_v1"
        private const val PROVIDER = "AndroidKeyStore"
    }
}
